from typing import List

def minimumIncrements(nums: List[int], target: List[int]) -> int:
    n = len(target)
    # dp[mask] 表示達成 mask 中對應的目標所需的最小操作次數
    # 初始化為無限大，dp[0] = 0
    dp = [float('inf')] * (1 << n)
    dp[0] = 0

    for num in nums:
        # 預先計算這個 num 到每個 target[j] 的下一個倍數所需的距離
        costs = []
        for t in target:
            if num % t == 0:
                costs.append(0)
            else:
                # 計算到下一個倍數需要的增量：t * (num // t + 1) - num
                cost = t * (num // t + 1) - num
                costs.append(cost)

        # 從後往前更新 DP，避免同一個 nums 被重複計算（類似 0/1 背包）
        for mask in range((1 << n) - 1, -1, -1):
            if dp[mask] == float('inf'):
                continue

            # 嘗試將目前的 num 轉化為任何一個 target[j] 的倍數
            for j in range(n):
                if not (mask & (1 << j)):
                    new_mask = mask | (1 << j)
                    dp[new_mask] = min(dp[new_mask], dp[mask] + costs[j])

    return int(dp[(1 << n) - 1])
```

