    for i in range(n):
        for j in range(m):
            rem = nums[i] % target[j]
            if rem == 0:
                costs[i][j] = 0
            else:
                costs[i][j] = target[j] - rem

    # dp[mask] is the minimum cost to satisfy the subset of targets represented by mask.
    # We iterate through each number in nums and try to assign it to an unsatisfied target.
    dp = [float('inf')] * (1 << m)
    dp[0] = 0

    for i in range(n):
        # To ensure we use a distinct num for each target, we update the DP table.
        # We iterate backwards or use a copy to prevent using the same nums[i] multiple times for one mask.
        new_dp = dp[:]
        for mask in range((1 << m) - 1):
            if dp[mask] == float('inf'):
                continue
