                if not (mask & (1 << j)):
                    next_mask = mask | (1 << j)
                    new_cost = dp[mask] + costs[i][j]
                    if new_cost < new_dp[next_mask]:
                        new_dp[next_mask] = new_cost
        dp = new_dp

