from typing import List

def minZeroArray(nums: List[int], queries: List[List[int]]) -> int:
    n = len(nums)

    # If already zero, return 0
    if all(x == 0 for x in nums):
        return 0

    def can_form(target, available_vals):
        if target == 0:
            return True
        dp = [False] * (target + 1)
        dp[0] = True
        for v in available_vals:
            # Optimization: only iterate if v <= target
            if v > target:
                continue
            for s in range(target, v - 1, -1):
                if dp[s - v]:
                    dp[s] = True
            if dp[target]:
                return True
        return dp[target]

    # Try each k from 1 to len(queries)
    for k in range(1, len(queries) + 1):
        possible = True
        for j in range(n):
            if nums[j] == 0:
                continue

            # Collect values of all queries i < k that cover index j
            available = []
            for i in range(k):
                l, r, v = queries[i]
                if l <= j <= r:
                    available.append(v)

            if not can_form(nums[j], available):
                possible = False
                break

        if possible:
            return k

    return -1
