def maxScore(a: List[int], b: List[int]) -> int:
    # dp[j] represents the max score using first j elements of a 
    # with some prefix of b. We use -infinity to handle negative values.
    dp = [float('-inf')] * 5
    dp[0] = 0

    for x in b:
        # Update backwards to avoid using the same element multiple times in one pass
        for j in range(4, 0, -1):
