from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m = len(coins)
    n = len(coins[0])

    # dp[i][j][k] is the max coins at (i, j) with k neutralizations used.
    # We use -float('inf') to represent unreachable states.
    # Since we only need the previous row/column, we could optimize space, 
    # but m, n <= 500 and k=3 fits in memory comfortably as a 3D array or 2D list of lists.
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]

    # Initialize starting point (0, 0)
    val = coins[0][0]
    if val >= 0:
        dp[0][0][0] = val
    else:
        # Option 1: Don't neutralize the robber at (0, 0)
        dp[0][0][0] = val
        # Option 2: Neutralize the robber at (0, 0)
        dp[0][0][1] = 0

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            val = coins[i][j]
            # Possible previous states from top (i-1, j) or left (i, j-1)
            prev_states = []
            if i > 0:
                prev_states.extend(dp[i-1][j])
            if j > 0:
                prev_states.extend(dp[i][j-1])

            max_prev = max(prev_states)
            if max_prev == -float('inf'):
                continue

            # We want to find the best way to reach (i, j) using k neutralizations.
            # However, standard DP transition is easier: 
            # for each k, dp[i][j][k] = max(dp[prev][k] + val_with_neutralization_logic)

            # To handle the "at most 2" logic correctly with negative values:
            # If current cell >= 0:
            if val >= 0:
                for k in range(3):
                    res = -float('inf')
                    if i > 0: res = max(res, dp[i-1][j][k])
                    if j > 0: res = max(res, dp[i][j-1][k])
                    dp[i][j][k] = res + val
            else:
                # If current cell < 0 (robber):
                for k in range(3):
                    # Case A: Don't neutralize this robber
                    res_no_neut = -float('inf')
                    if i > 0: res_no_neut = max(res_no_neut, dp[i-1][j][k])
                    if j > 0: res_no_neut = max(res_no_neut, dp[i][j-1][k])
                    dp[i][j][k] = max(dp[i][j][k], res_no_neut + val)

                    # Case B: Neutralize this robber (requires k > 0)
                    if k > 0:
                        res_neut = -float('inf')
                        if i > 0: res_neut = max(res_neut, dp[i-1][j][k-1])
                        if j > 0: res_neut = max(res_neut, dp[i][j-1][k-1])
                        dp[i][j][k] = max(dp[i][j][k], res_neut)

    return int(max(dp[m-1][n-1]))

