def minMaxSums(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    n = len(nums)
    nums.sort()

    # Precompute combinations C(n, r)
    C = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        C[i][0] = 1
        for j in range(1, min(i, k) + 1):
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD

    total_min = 0
    total_max = 0

    # Contribution of nums[i] as Minimum:
    # It is the minimum if we pick it and pick (r-1) elements from the (n-1-i) elements larger than it.
    for i in range(n):
        for r in range(1, k + 1):
            if n - 1 - i >= r - 1:
                total_min = (total_min + nums[i] * C[n - 1 - i][r - 1]) % MOD

    # Contribution of nums[i] as Maximum:
    # It is the maximum if we pick it and pick (r-1) elements from the (i) elements smaller than it.
    for i in range(n):
        for r in range(1, k + 1):
            if i >= r - 1:
                total_max = (total_max + nums[i] * C[i][r - 1]) % MOD

    return (total_min + total_max) % MOD
